import java.util.*;

class Edge {
    int y, c, f, cost;
    Edge() {}
    Edge(int y, int c, int f, int cost) {
        this.y = y;
        this.c = c;
        this.f = f;
        this.cost = cost;
    }
}

public class Main {
    static List<Edge> e_list = new ArrayList<>();
    static final int MAXNODES = 14043;
    static List<Integer>[] adj = new ArrayList[MAXNODES];
    static long total_flow_cost = 0;
    static long[] dist_arr = new long[MAXNODES];
    static int[] parent_node = new int[MAXNODES];
    static int[] parent_edge_idx = new int[MAXNODES];
    static int[] in_queue_flag = new int[MAXNODES];

    static final long INF_VAL = (long)1e18;
    static int s_node = MAXNODES - 2;
    static int t_node = MAXNODES - 1;

    static {
        for (int i = 0; i < MAXNODES; i++) {
            adj[i] = new ArrayList<>();
        }
    }

    static int residual_capacity(int idx) {
        return e_list.get(idx).c - e_list.get(idx).f;
    }

    static void find_augmenting_path() {
        for (int i = 0; i < MAXNODES; i++) {
            dist_arr[i] = INF_VAL;
            parent_node[i] = -1;
            parent_edge_idx[i] = -1;
            in_queue_flag[i] = 0;
        }
        dist_arr[s_node] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(s_node);
        in_queue_flag[s_node] = 1;
        while (!q.isEmpty()) {
            int u = q.poll();
            in_queue_flag[u] = 0;
            for (int e_idx : adj[u]) {
                if (residual_capacity(e_idx) == 0) continue;
                int cst = e_list.get(e_idx).cost;
                int v = e_list.get(e_idx).y;
                if (dist_arr[v] > dist_arr[u] + cst) {
                    dist_arr[v] = dist_arr[u] + cst;
                    parent_node[v] = u;
                    parent_edge_idx[v] = e_idx;
                    if (in_queue_flag[v] == 0) {
                        in_queue_flag[v] = 1;
                        q.offer(v);
                    }
                }
            }
        }
        int cur = t_node;
        while (cur != s_node) {
            int e_idx = parent_edge_idx[cur];
            e_list.get(e_idx).f++;
            e_list.get(e_idx ^ 1).f--;
            cur = parent_node[cur];
        }
        total_flow_cost += dist_arr[t_node];
    }

    static void insert_edge(int from, int to, int cap, int cst) {
        adj[from].add(e_list.size());
        e_list.add(new Edge(to, cap, 0, cst));
        adj[to].add(e_list.size());
        e_list.add(new Edge(from, 0, 0, -cst));
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();
        int c = sc.nextInt();
        int d = sc.nextInt();

        for (int i = 0; i < k; i++) {
            int x = sc.nextInt();
            insert_edge(s_node, x, 1, 0);
        }

        int tt = 101;
        for (int i = 0; i < tt; i++) {
            insert_edge(1 + i * n, t_node, k, i * c);
        }

        for (int i = 0; i < m; i++) {
            int x = sc.nextInt();
            int y = sc.nextInt();
            for (int j = 0; j < tt - 1; j++) {
                insert_edge(x + j * n, y + j * n + n, 1, d * (j * 2 + 1));
                insert_edge(y + j * n, x + j * n + n, 1, d * (j * 2 + 1));
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < tt - 1; j++) {
                insert_edge(i + j * n, i + j * n + n, k, 0);
            }
        }

        for (int i = 0; i < k; i++) {
            find_augmenting_path();
        }

        System.out.println(total_flow_cost);
        sc.close();
    }
}
